-- Liga cada produto ao SKU real da DingConnect (confirmado por comparacao exata dos
-- valores reais devolvidos por GetProducts com os produtos ja existentes) para que o
-- envio da recarga (SendTransfer) va para o produto certo. is_send_value_range = true
-- indica um SKU de valor livre, onde SendValue = payer_amount_cents/100 em vez de um
-- ReceiveValue fixo. Match por (provider_code, amount, currency) em vez de id, para nao
-- depender da sequencia exata de auto-increment entre ambientes.

ALTER TABLE airtime_products ADD COLUMN dingconnect_sku_code VARCHAR(50);
ALTER TABLE airtime_products ADD COLUMN dingconnect_send_value_range BOOLEAN NOT NULL DEFAULT FALSE;

UPDATE airtime_products p SET dingconnect_sku_code = '93A865AO21089', dingconnect_send_value_range = FALSE FROM operators o WHERE p.operator_id = o.id AND o.provider_code = '93A865AO' AND p.amount = 2244.68 AND p.currency = 'AOA';
